pub fn rsplit(a: Vec<String>, sep: String, maxsplit: u8) -> Vec<Vec<String>> {
    // sep is guaranteed non-empty by the problem statement.
    if maxsplit == 0 {
        return a.into_iter().map(|s| vec![s]).collect();
    }

    let mut out = Vec::with_capacity(a.len());

    for s in a {
        if s.is_empty() {
            out.push(vec![String::new()]);
            continue;
        }

        // Perform up to `maxsplit` right-to-left splits and then reverse to get
        // left-to-right order of parts.
        let parts: Vec<String> = s
            .rsplitn((maxsplit as usize) + 1, &sep)
            .map(|p| p.to_string())
            .collect::<Vec<_>>()
            .into_iter()
            .rev()
            .collect();

        // `rsplitn` always yields at least one part.
        out.push(parts);
    }

    out
}